<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Audit,Security,Problem};
final class Membership
{
 public function __construct(private Database $db){}
 public function storage():void {
  if($this->db->featureReady('membership28'))return;
  (new AtlasData($this->db))->storage();(new Classifications($this->db))->storage();(new Knowledge($this->db))->storage();
  try{$this->db->run('SELECT id FROM m_service_restrictions LIMIT 0');$this->db->run('SELECT booking_id FROM m_credit_allocations LIMIT 0');}
  catch(\PDOException $e){if((int)($e->errorInfo[1]??0)!==1146)throw $e;if($this->db->pdo->inTransaction())throw new \LogicException('Prepare membership storage before transaction');foreach(explode(';',file_get_contents(__DIR__.'/../../database/membership28.sql')) as $sql){if(trim($sql)!=='')$this->db->run($sql);}}
  $this->db->markFeatureReady('membership28');
 }
 public function policy():array {$this->storage();return $this->db->one('SELECT * FROM m_service_policy WHERE id=1');}
 public function write(callable $fn):mixed {$this->storage();return $this->db->tx(function()use($fn){$this->db->one('SELECT id FROM m_installation WHERE id=1 FOR UPDATE');return $fn();});}
 public function history(array $a,string $subject,string $action,array $before,array $after):void {$this->db->run('INSERT INTO m_knowledge_history VALUES(?,?,?,?,?,?,?)',[Security::id(),$subject,$a['user_id'],$action,json_encode($before,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),json_encode($after,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),time()]);}
 public function central(array $a):void {(new Policy($this->db))->admin($a,true);}
 public function allowed(array $a,string $org,string $permission):bool {
  if(($a['realm']??'')==='admin'){try{$this->central($a);return true;}catch(Problem $e){return false;}}
  (new Policy($this->db))->user($a);$column=$permission==='verify'?'verify_organizations':'review_members';
  return (bool)$this->db->one("SELECT d.id FROM m_delegations d WHERE d.user_id=? AND d.active=1 AND d.$column=1 AND ((d.scope_kind='organization' AND d.scope_id=?) OR (d.scope_kind='network' AND EXISTS(SELECT 1 FROM m_network_organizations nox JOIN m_networks n ON n.id=nox.network_id AND n.active=1 WHERE nox.network_id=d.scope_id AND nox.org_id=?))) LIMIT 1",[$a['user_id'],$org,$org]);
 }
 public function verified(string $org):bool {return (bool)$this->db->one("SELECT o.id FROM m_organizations o JOIN m_organization_verification v ON v.org_id=o.id AND v.status='approved' LEFT JOIN m_organization_profiles p ON p.org_id=o.id WHERE o.id=? AND o.active=1 AND p.merged_into IS NULL",[$org]);}
 public function member(string $uid,?string $org=null):bool {
  $this->storage();return (bool)$this->db->one("SELECT m.org_id FROM m_memberships m JOIN m_organizations o ON o.id=m.org_id AND o.active=1 JOIN m_organization_verification v ON v.org_id=o.id AND v.status='approved' LEFT JOIN m_membership_requests r ON r.org_id=m.org_id AND r.user_id=m.user_id LEFT JOIN m_organization_profiles p ON p.org_id=o.id WHERE m.user_id=? AND (r.id IS NULL OR (r.status='approved' AND r.starts_at<=? AND (r.ends_at IS NULL OR r.ends_at>?))) AND p.merged_into IS NULL".($org?' AND m.org_id=?':'').' LIMIT 1',[$uid,time(),time(),...($org?[$org]:[])]);
 }
 public function profile(string $uid):array {$this->storage();$row=$this->db->one('SELECT novice FROM m_service_profiles WHERE user_id=?',[$uid]);return ['tier'=>$this->member($uid)?'member':'independent','novice'=>$row?(bool)$row['novice']:true];}
 public function savePolicy(array $a,array $d):void {$this->central($a);$this->write(function()use($a,$d){$ranges=['enabled'=>[0,1],'independent_quota'=>[0,100],'member_quota'=>[0,100],'max_pending'=>[1,20],'response_hours'=>[1,168],'cancel_hours'=>[0,168],'cycle_day'=>[1,28],'behavior_days'=>[1,365],'second_days'=>[1,365],'third_days'=>[1,365]];$old=$this->policy();$values=[];foreach($ranges as $key=>[$min,$max])$values[]=Policy::integer($d[$key]??$old[$key],$min,$max);$zone=Policy::text($d['timezone']??$old['timezone'],50);if(!in_array($zone,\DateTimeZone::listIdentifiers(),true))throw new Problem('INVALID_TIMEZONE','منطقه زمانی معتبر نیست.');$values[]=$zone;$values[]=$a['user_id'];$values[]=time();$this->db->run('UPDATE m_service_policy SET '.implode('=?,',array_keys($ranges)).'=?,timezone=?,updated_by=?,updated_at=? WHERE id=1',$values);(new Audit($this->db))->add($a['user_id'],'admin','membership.policy_changed');});}
 public function experienceLevel(array $a,string $uid,bool $novice):void {$this->central($a);$this->write(function()use($a,$uid,$novice){if(!$this->db->one("SELECT id FROM m_users WHERE id=? AND status='active'",[$uid]))throw new Problem('NOT_FOUND','کاربر فعال پیدا نشد.',404);$this->db->run('INSERT INTO m_service_profiles VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE novice=VALUES(novice),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)',[$uid,(int)$novice,$a['user_id'],time()]);(new Audit($this->db))->add($a['user_id'],'admin','membership.experience_level',$uid);});}
 public function admission(string $mentor):array {$this->storage();return $this->db->one('SELECT accept_novices,max_pending FROM m_mentor_admission WHERE mentor_id=?',[$mentor])??['accept_novices'=>1,'max_pending'=>10];}
 public function saveAdmission(array $a,array $d):void {(new Policy($this->db))->mentor($a,true);$this->write(function()use($a,$d){$this->db->run('INSERT INTO m_mentor_admission VALUES(?,?,?) ON DUPLICATE KEY UPDATE accept_novices=VALUES(accept_novices),max_pending=VALUES(max_pending)',[$a['user_id'],Policy::integer($d['accept_novices']??0,0,1),Policy::integer($d['max_pending']??10,1,100)]);(new Audit($this->db))->add($a['user_id'],'site','mentor.admission_changed',$a['user_id']);});}
 public function eligibility(string $uid,string $mentor,bool $newRequest=true):array {
  $p=$this->policy();if(!$p['enabled'])return ['allowed'=>true,'reason'=>''];$profile=$this->profile($uid);$ad=$this->admission($mentor);
  $block=$this->db->one('SELECT reason,ends_at FROM m_service_restrictions WHERE user_id IN (?,?) AND revoked_at IS NULL AND starts_at<=? AND ends_at>? ORDER BY ends_at DESC LIMIT 1',[$uid,$mentor,time(),time()]);
  if($block)return ['allowed'=>false,'reason'=>'پذیرش درخواست به‌دلیل محدودیت خدمات مشاوره تا '.Consultations::sessionLabel((int)$block['ends_at']).' ممکن نیست.'];
  if($profile['novice']&&!$ad['accept_novices'])return ['allowed'=>false,'reason'=>'این مرشد در حال حاضر مخاطب تازه‌کار نمی‌پذیرد.'];
  if($newRequest&&(int)$this->db->run("SELECT COUNT(*) FROM m_bookings WHERE mentor_id=? AND state='pending' AND expires_at>?",[$mentor,time()])->fetchColumn()>=(int)$ad['max_pending'])return ['allowed'=>false,'reason'=>'ظرفیت درخواست‌های در انتظار مرشد تکمیل است.'];
  $s=$this->db->one('SELECT acceptance_paused FROM m_schedule_settings WHERE mentor_id=?',[$mentor]);if($newRequest&&(!$s||$s['acceptance_paused']))return ['allowed'=>false,'reason'=>'پذیرش درخواست جدید مرشد متوقف است.'];return ['allowed'=>true,'reason'=>''];
 }
 public function organizations(string $query=''):array {$this->storage();$q=Policy::query($query);return $this->db->all("SELECT o.id,o.name,COALESCE(v.status,'pending') AS verification_status FROM m_organizations o LEFT JOIN m_organization_verification v ON v.org_id=o.id LEFT JOIN m_organization_profiles p ON p.org_id=o.id WHERE o.active=1 AND p.merged_into IS NULL AND o.name LIKE ? ORDER BY o.name LIMIT 50",[$q]);}
 public function requestMembership(array $a,array $d):string {(new Policy($this->db))->user($a);return $this->write(function()use($a,$d){$org=Policy::text($d['org_id']??'',32);if(!$this->db->one('SELECT id FROM m_organizations WHERE id=? AND active=1',[$org]))throw new Problem('NOT_FOUND','مجموعه پیدا نشد.',404);$note=Policy::text($d['note']??'',4000,10);$kind=Policy::choice($d['relation_kind']??'member',['member','responsible','collaborator']);$old=$this->db->one('SELECT id,status,note,relation_kind FROM m_membership_requests WHERE org_id=? AND user_id=? FOR UPDATE',[$org,$a['user_id']]);if($old&&in_array($old['status'],['approved','pending'],true)){if($old['status']==='pending'&&($old['note']!==$note||$old['relation_kind']!==$kind))throw new Problem('CONFLICT','درخواست در حال بررسی است.',409);return $old['id'];}$id=$old['id']??Security::id();$this->db->run("INSERT INTO m_membership_requests(id,org_id,user_id,relation_kind,status,note,review_note,starts_at,updated_at) VALUES(?,?,?,?,'pending',?,'',?,?) ON DUPLICATE KEY UPDATE status='pending',note=VALUES(note),relation_kind=VALUES(relation_kind),updated_at=VALUES(updated_at)",[$id,$org,$a['user_id'],$kind,$note,time(),time()]);(new Audit($this->db))->add($a['user_id'],'site','membership.requested',$id);return $id;});}
 public function reviewMembership(array $a,array $d):void {$this->write(function()use($a,$d){$id=Policy::text($d['id']??'',32);$r=$this->db->one('SELECT * FROM m_membership_requests WHERE id=? FOR UPDATE',[$id]);if(!$r||!$this->allowed($a,$r['org_id'],'members'))throw new Problem('ACCESS_DENIED','مجوز بررسی این عضویت را ندارید.',403);if(($a['realm']??'')!=='admin'&&$r['user_id']===$a['user_id'])throw new Problem('ACCESS_DENIED','تأیید عضویت خود به مدیر مرکزی نیاز دارد.',403);$status=Policy::choice($d['status']??'',['approved','rejected','clarification','suspended']);$note=Policy::text($d['review_note']??'',4000,3);if($status==='approved'&&!$this->verified($r['org_id']))throw new Problem('ORGANIZATION_UNVERIFIED','ابتدا هویت مجموعه باید تأیید شود.',409);
  $this->db->run('UPDATE m_membership_requests SET status=?,review_note=?,reviewed_by=?,reviewed_at=?,updated_at=?,ends_at=? WHERE id=?',[$status,$note,$a['user_id'],time(),time(),$status==='suspended'?time():null,$id]);if($status==='approved')$this->db->run('INSERT IGNORE INTO m_memberships VALUES(?,?)',[$r['org_id'],$r['user_id']]);else $this->db->run('DELETE FROM m_memberships WHERE org_id=? AND user_id=?',[$r['org_id'],$r['user_id']]);$this->history($a,$id,'membership.review',$r,['status'=>$status,'reason'=>$note,'reviewed_by'=>$a['user_id']]);$au=new Audit($this->db);$au->add($a['user_id'],$a['realm'],'membership.'.$status,$id);$au->notify($r['user_id'],'وضعیت عضویت مجموعه تغییر کرد',$note,'/account');});}
 public function proposeOrganization(array $a,array $d):string {(new Policy($this->db))->user($a);return $this->write(function()use($a,$d){$name=Policy::text($d['name']??'',180,3);$description=Policy::text($d['description']??'',6000,12);$contact=Policy::text($d['contact_note']??'',2000,5);$evidence=Policy::text($d['evidence']??'',6000,5);$type=Policy::text($d['org_type']??'',24);if(!$this->db->one('SELECT id FROM m_org_types WHERE id=? AND active=1',[$type]))throw new Problem('INVALID_INPUT','نوع مجموعه را از فهرست موجود انتخاب کنید.');[$province,$county]=(new AtlasData($this->db))->location($d['province_id']??'',$d['county_id']??'');if(!$province)throw new Problem('INVALID_PLACE','استان مجموعه لازم است.');if($this->db->one('SELECT id FROM m_organizations WHERE name=?',[$name]))throw new Problem('DUPLICATE','این نام قبلاً ثبت شده؛ ابتدا مجموعه‌های موجود را جست‌وجو کنید.',409);if((int)$this->db->run('SELECT COUNT(*) FROM m_organization_verification WHERE submitted_by=? AND updated_at>?',[$a['user_id'],time()-86400])->fetchColumn()>=3)throw new Problem('RATE_LIMITED','حداکثر سه معرفی در روز مجاز است.',429);$id=Security::id();$this->db->run('INSERT INTO m_organizations(id,name) VALUES(?,?)',[$id,$name]);$this->db->run('INSERT INTO m_organization_profiles(org_id,description,org_type,province_id,county_id,updated_at) VALUES(?,?,?,?,?,?)',[$id,$description,$type,$province,$county,time()]);$this->db->run("INSERT INTO m_organization_verification(org_id,status,submitted_by,contact_note,evidence,review_note,updated_at) VALUES(?,'pending',?,?,?,'',?)",[$id,$a['user_id'],$contact,$evidence,time()]);(new Audit($this->db))->add($a['user_id'],'site','organization.verification_requested',$id);return $id;});}
 public function reviewOrganization(array $a,array $d):void {$this->write(function()use($a,$d){$id=Policy::text($d['id']??'',32);if(!$this->allowed($a,$id,'verify'))throw new Problem('ACCESS_DENIED','مجوز احراز این مجموعه را ندارید.',403);$v=$this->db->one('SELECT * FROM m_organization_verification WHERE org_id=? FOR UPDATE',[$id]);if(!$v)throw new Problem('NOT_FOUND','درخواست احراز پیدا نشد.',404);if(($a['realm']??'')!=='admin'&&$v['submitted_by']===$a['user_id'])throw new Problem('ACCESS_DENIED','تأیید مجموعهٔ معرفی‌شده توسط خودتان به مدیر مرکزی نیاز دارد.',403);$status=Policy::choice($d['status']??'',['approved','rejected','clarification','suspended']);$note=Policy::text($d['review_note']??'',4000,3);$this->db->run('UPDATE m_organization_verification SET status=?,review_note=?,reviewed_by=?,reviewed_at=?,updated_at=? WHERE org_id=?',[$status,$note,$a['user_id'],time(),time(),$id]);$this->history($a,$id,'organization.identity_review',$v,['status'=>$status,'reason'=>$note,'reviewed_by'=>$a['user_id']]);$au=new Audit($this->db);$au->add($a['user_id'],$a['realm'],'organization.identity_'.$status,$id);if($v['submitted_by'])$au->notify($v['submitted_by'],'نتیجهٔ احراز مجموعه',$note,'/account');});}
 public function network(array $a,array $d):string {$this->central($a);return $this->write(function()use($a,$d){$id=Policy::text($d['id']??'',32,0)?:Security::id();if(!Security::validId($id))throw new Problem('INVALID_INPUT','شناسه معتبر نیست.');[$province,$county]=(new AtlasData($this->db))->location($d['province_id']??'',$d['county_id']??'');$this->db->run('INSERT INTO m_networks VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),activity=VALUES(activity),province_id=VALUES(province_id),county_id=VALUES(county_id),active=VALUES(active),updated_at=VALUES(updated_at)',[$id,Policy::text($d['name']??'',180,3),Policy::text($d['description']??'',6000,3),Policy::text($d['activity']??'',2000,3),$province,$county,Policy::integer($d['active']??1,0,1),$a['user_id'],time()]);(new Audit($this->db))->add($a['user_id'],'admin','network.saved',$id);return $id;});}
 public function linkNetwork(array $a,string $network,string $org,bool $remove):void {$this->central($a);$this->write(function()use($a,$network,$org,$remove){if(!$this->db->one('SELECT id FROM m_networks WHERE id=?',[$network])||!$this->db->one('SELECT id FROM m_organizations WHERE id=?',[$org]))throw new Problem('NOT_FOUND','شبکه یا مجموعه پیدا نشد.',404);$this->db->run($remove?'DELETE FROM m_network_organizations WHERE network_id=? AND org_id=?':'INSERT IGNORE INTO m_network_organizations VALUES(?,?)',[$network,$org]);(new Audit($this->db))->add($a['user_id'],'admin',$remove?'network.organization_removed':'network.organization_linked',$org);});}
 public function delegate(array $a,array $d):void {$this->central($a);$this->write(function()use($a,$d){$uid=Policy::text($d['user_id']??'',32);$kind=Policy::choice($d['scope_kind']??'',['organization','network']);$id=Policy::text($d['scope_id']??'',32);$table=$kind==='network'?'m_networks':'m_organizations';if(!$this->db->one('SELECT id FROM '.$table.' WHERE id=?',[$id])||!$this->db->one("SELECT id FROM m_users WHERE id=? AND status='active'",[$uid]))throw new Problem('NOT_FOUND','حساب یا حوزه پیدا نشد.',404);$verify=Policy::integer($d['verify_organizations']??0,0,1);$members=Policy::integer($d['review_members']??0,0,1);$active=Policy::integer($d['active']??1,0,1);$before=$this->db->one('SELECT * FROM m_delegations WHERE user_id=? AND scope_kind=? AND scope_id=?',[$uid,$kind,$id])??[];$this->history($a,$uid,'membership.delegation',$before,['scope_kind'=>$kind,'scope_id'=>$id,'verify'=>$verify,'members'=>$members,'active'=>$active]);$this->db->run('INSERT INTO m_delegations VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE verify_organizations=VALUES(verify_organizations),review_members=VALUES(review_members),active=VALUES(active),granted_by=VALUES(granted_by),created_at=VALUES(created_at)',[Security::id(),$uid,$kind,$id,$verify,$members,$active,$a['user_id'],time()]);(new Audit($this->db))->add($a['user_id'],'admin','network.delegation_changed',$uid);});}
}
